// RetrieveDisputePerformanceArgs holds the arguments for the retrieve-dispute-performance endpoint.
type RetrieveDisputePerformanceArgs struct {
	// Period The date or date range for which to retrieve dispute performance data.
	//
	// **Supported formats:**
	// - **Specific date**: `YYYY-MM-DD` (e.g., "2024-01-15")
	// - **Date range**: `YYYY-MM-DD..YYYY-MM-DD` (e.g., "2024-01-01..2024-01-31")
	Period string `json:"period"`
	// IncludeWon Whether to include won disputes in the performance data. Default is `true`.
	IncludeWon *bool `json:"include_won,omitempty"`
	// IncludeLost Whether to include lost disputes in the performance data. Default is `true`.
	IncludeLost *bool `json:"include_lost,omitempty"`
	// IncludeInProgress Whether to include in-progress (non-finalized) disputes in the performance data. Default is `true`.
	IncludeInProgress *bool `json:"include_in_progress,omitempty"`
}

// RetrieveDisputePerformanceResult is the result of the retrieve-dispute-performance endpoint.
type RetrieveDisputePerformanceResult struct {
	// StartDate The start date of the performance period in ISO 8601 format (YYYY-MM-DD).
	//
	// This represents the beginning of the date range for which performance data is calculated.
	// For single day requests, this will be the same as end_date.
	StartDate string `json:"start_date"`
	// EndDate The end date of the performance period in ISO 8601 format (YYYY-MM-DD).
	//
	// This represents the end of the date range for which performance data is calculated.
	// For single day requests, this will be the same as start_date.
	EndDate string `json:"end_date"`
	// Amount The total amount of all captured transactions in the period, expressed in the smallest currency unit. E.g. 100 THB is represented as 10000. And 100 JPY is represented as 100.
	Amount float64 `json:"amount"`
	// Count The total number of captured transactions in the period.
	Count float64 `json:"count"`
	// Average The average captured transaction amount in the smallest currency unit.
	Average *float64 `json:"average,omitempty"`
	// Change The percentage change in total amount compared to the previous equivalent period.
	//
	// **Values:**
	//
	// - **Positive**: Indicates an increase in compared to the previous period
	// - **Negative**: Indicates a decrease in compared to the previous period
	// - **Null**: When there are no transactions in the previous period (division by zero)
	//
	// **Example:** A value of 15.5 means increased by 15.5% compared to the previous period.
	Change *float64 `json:"change,omitempty"`
	// Granularity The time granularity used for transaction breakdown in the response.
	//
	// **Granularity is determined by the date range:**
	//
	// - **hourly**: Single day requests (0 days)
	// - **daily**: 1-83 days range
	// - **weekly**: 84-167 days range
	// - **monthly**: 168+ days range
	//
	// This affects how the transactions array is grouped and formatted. one of: "hourly", "daily", "weekly", "monthly"
	Granularity string `json:"granularity"`
	// Transactions Array of transaction breakdowns grouped by the specified granularity.
	//
	// **Each transaction object contains:**
	//
	// - `total_amount`: Total amount for the period in smallest currency unit
	// - `total_count`: Number of transactions for the period
	// - `period_start`: Start of the period (format varies by granularity)
	//
	// **Period start formats:**
	//
	// - **hourly**: "HH:00:00" (e.g., "14:00:00")
	// - **daily**: "YYYY-MM-DD" ISO 8601 format (e.g., "2024-01-15")
	// - **weekly**: "YYYY-MM-DD" (week start date)
	// - **monthly**: "YYYY-MM-DD" (month start date)
	//
	// **Note:** Array may be empty if no transactions exist for the specified date range.
	Transactions []map[string]any `json:"transactions"`
}

